 <body>
   <main>
     <section class="form-card" aria-labelledby="page-title">
       <p class="eyebrow">Preferences</p>
       <h1 id="page-title">Stay in the loop</h1>
       <p class="intro">Choose the notification channel that works best for you.</p>

       <form id="notification-form">
         <div class="form-field">
           <fieldset>
             <legend>How do you prefer to receive notifications?</legend>
             <div class="radio-options">
