               <label class="radio-option" for="notification-push">
                 <input type="radio" id="notification-push" name="notificationPreference" value="Push Notifications">
                 <span>Push Notifications</span>
               </label>
             </div>
           </fieldset>
         </div>

         <button type="submit">Save preference</button>
         <p class="status" id="form-status" role="status" aria-live="polite"></p>
       </form>
     </section>
   </main>

